function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'BookMyShow' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with BookMyShow(n, m).';
  const [n, m] = args[0];
  if (!Number.isInteger(n) || n < 1 || n > 50000) return 'n is a whole number from 1 to 5 * 10^4.';
  if (!Number.isInteger(m) || m < 1 || m > 1000000000) return 'm is a whole number from 1 to 10^9.';
  if (operations.length - 1 > 50000) return 'At most 5 * 10^4 calls to gather and scatter.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'gather' && operations[i] !== 'scatter') return 'Only gather and scatter can follow the constructor.';
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 2) return operations[i] + ' needs k and maxRow.';
    if (!Number.isInteger(a[0]) || a[0] < 1 || a[0] > 1000000000) return 'k is a whole number from 1 to 10^9.';
    if (!Number.isInteger(a[1]) || a[1] < 0 || a[1] > n - 1) return 'maxRow is between 0 and n - 1.';
  }
  return null;
}

