class BookMyShow {
  constructor(n, m) {
    this.m = m;
    this.size = 1;
    while (this.size < n) {
      this.size *= 2;
    }
    this.maxFree = new Array(2 * this.size).fill(0).fill(m, this.size, this.size + n);
    this.sumFree = new Array(2 * this.size).fill(0).fill(m, this.size, this.size + n);
    for (let node = this.size - 1; node >= 1; node--) {
      this.pull(node);
    }
    this.firstOpen = 0;
  }

  pull(node) {
    this.maxFree[node] = Math.max(this.maxFree[2 * node], this.maxFree[2 * node + 1]);
    this.sumFree[node] = this.sumFree[2 * node] + this.sumFree[2 * node + 1];
  }

  take(row, count) {
    let node = this.size + row;
    this.maxFree[node] -= count;
    this.sumFree[node] -= count;
    for (node = node >> 1; node >= 1; node = node >> 1) {
      this.pull(node);
    }
  }

  freeUpTo(maxRow) {
    let node = this.size + maxRow;
    let total = this.sumFree[node];
    while (node > 1) {
      if (node % 2 === 1) {
        total += this.sumFree[node - 1];
      }
      node = node >> 1;
    }
    return total;
  }

  gather(k, maxRow) {
    if (this.maxFree[1] < k) {
      return [];
    }
    let node = 1;
    while (node < this.size) {
      node = this.maxFree[2 * node] >= k ? 2 * node : 2 * node + 1;
    }
    const row = node - this.size;
    if (row > maxRow) {
      return [];
    }
    const seat = this.m - this.sumFree[node];
    this.take(row, k);
    return [row, seat];
  }

  scatter(k, maxRow) {
    if (this.freeUpTo(maxRow) < k) {
      return false;
    }
    while (k > 0) {
      const empty = this.sumFree[this.size + this.firstOpen];
      const used = Math.min(k, empty);
      this.take(this.firstOpen, used);
      k -= used;
      if (used === empty) {
        this.firstOpen++;
      }
    }
    return true;
  }
}

