class BookMyShow {
  constructor(n, m) {
    this.m = m;
    this.taken = new Array(n).fill(0);
  }
  gather(k, maxRow) {
    for (let r = 0; r <= maxRow; r++) {
      if (this.m - this.taken[r] >= k) {
        const c = this.taken[r];
        this.taken[r] += k;
        return [r, c];
      }
    }
    return [];
  }
  scatter(k, maxRow) {
    let empty = 0;
    for (let r = 0; r <= maxRow; r++) empty += this.m - this.taken[r];
    if (empty < k) return false;
    for (let r = 0; r <= maxRow && k > 0; r++) {
      const seats = Math.min(k, this.m - this.taken[r]);
      this.taken[r] += seats;
      k -= seats;
    }
    return true;
  }
}

