function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 50000 : int(1, 40)) : int(1, 4);
  const m = large ? (rand() < 0.5 ? 1000000000 : int(1, 100)) : int(1, 6);
  const calls = large ? 499 : int(1, 15);
  const operations = ['BookMyShow'];
  const args = [[n, m]];
  for (let i = 0; i < calls; i++) {
    const maxRow = rand() < 0.3 ? n - 1 : int(0, n - 1);
    if (rand() < 0.5) {
      operations.push('gather');
      args.push([int(1, Math.min(1000000000, m + 1)), maxRow]);
    } else {
      // Scatter sizes reach a few rows' worth so groups span rows and sometimes fail.
      operations.push('scatter');
      args.push([int(1, Math.min(1000000000, m * (large ? 60 : 3))), maxRow]);
    }
  }
  return [operations, args];
}
